#!/usr/bin/env python3
"""A small persistent JSON key-value HTTP service."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote


MAX_BODY_BYTES = 1024 * 1024


class Store:
    def __init__(self, path: Path) -> None:
        self.path = path
        self.lock = threading.RLock()
        self.entries: dict[str, dict[str, object]] = {}
        self._load()

    def _load(self) -> None:
        try:
            with self.path.open(encoding="utf-8") as file:
                loaded = json.load(file)
            if not isinstance(loaded, dict):
                raise ValueError("root is not an object")
            self.entries = {
                key: entry
                for key, entry in loaded.items()
                if isinstance(key, str)
                and isinstance(entry, dict)
                and "value" in entry
                and (entry.get("expires_at") is None or isinstance(entry.get("expires_at"), (int, float)))
            }
            self._purge_expired(save=True)
        except FileNotFoundError:
            pass
        except (OSError, ValueError, json.JSONDecodeError) as error:
            print(f"Could not load data file: {error}", file=sys.stderr)

    def _purge_expired(self, save: bool = False) -> bool:
        now = time.time()
        expired = [key for key, entry in self.entries.items() if entry.get("expires_at") is not None and entry["expires_at"] <= now]
        for key in expired:
            del self.entries[key]
        if expired and save:
            self._save()
        return bool(expired)

    def _save(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        descriptor, temporary_name = tempfile.mkstemp(prefix=f".{self.path.name}.", dir=self.path.parent, text=True)
        try:
            with os.fdopen(descriptor, "w", encoding="utf-8") as file:
                json.dump(self.entries, file, ensure_ascii=False, separators=(",", ":"))
                file.flush()
                os.fsync(file.fileno())
            os.replace(temporary_name, self.path)
        except Exception:
            try:
                os.unlink(temporary_name)
            except FileNotFoundError:
                pass
            raise

    def get(self, key: str) -> object | None:
        with self.lock:
            if self._purge_expired():
                self._save()
            entry = self.entries.get(key)
            return None if entry is None else entry["value"]

    def put(self, key: str, value: object, ttl_seconds: float | None) -> bool:
        with self.lock:
            self._purge_expired()
            exists = key in self.entries
            self.entries[key] = {"value": value, "expires_at": None if ttl_seconds is None else time.time() + ttl_seconds}
            self._save()
            return exists

    def delete(self, key: str) -> bool:
        with self.lock:
            self._purge_expired()
            if key not in self.entries:
                return False
            del self.entries[key]
            self._save()
            return True

    def keys(self) -> list[str]:
        with self.lock:
            if self._purge_expired():
                self._save()
            return sorted(self.entries)


class Handler(BaseHTTPRequestHandler):
    store: Store

    def log_message(self, format: str, *args: object) -> None:
        print(f"{self.client_address[0]} - {format % args}", file=sys.stderr)

    def _respond(self, status: int, payload: object | None = None) -> None:
        self.send_response(status)
        if payload is not None:
            body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if payload is not None:
            self.wfile.write(body)

    def _error(self, status: int, message: str) -> None:
        self._respond(status, {"error": message})

    def _key(self) -> str | None:
        prefix = "/v1/kv/"
        if not self.path.startswith(prefix):
            return None
        encoded = self.path[len(prefix):]
        if not encoded or "/" in encoded or "?" in encoded:
            return None
        try:
            key = unquote(encoded, encoding="utf-8", errors="strict")
        except UnicodeDecodeError:
            return None
        return key if key and "/" not in key else None

    def _read_json(self) -> object | None:
        length = self.headers.get("Content-Length")
        try:
            size = int(length) if length is not None else -1
        except ValueError:
            size = -1
        if size < 0 or size > MAX_BODY_BYTES:
            self._error(HTTPStatus.REQUEST_ENTITY_TOO_LARGE, "request body must not exceed 1 MiB")
            return None
        try:
            return json.loads(self.rfile.read(size).decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self._error(HTTPStatus.BAD_REQUEST, "malformed JSON")
            return None

    def do_GET(self) -> None:
        if self.path == "/health":
            self._respond(HTTPStatus.OK, {"status": "ok"})
        elif self.path == "/v1/keys":
            self._respond(HTTPStatus.OK, {"keys": self.store.keys()})
        elif (key := self._key()) is not None:
            value = self.store.get(key)
            if value is None:
                self._error(HTTPStatus.NOT_FOUND, "key not found")
            else:
                self._respond(HTTPStatus.OK, {"key": key, "value": value})
        else:
            self._error(HTTPStatus.NOT_FOUND, "unknown route")

    def do_PUT(self) -> None:
        key = self._key()
        payload = self._read_json()
        if key is None:
            self._error(HTTPStatus.BAD_REQUEST, "invalid key or route")
        elif payload is None:
            return
        elif not isinstance(payload, dict) or "value" not in payload or set(payload) - {"value", "ttl_seconds"}:
            self._error(HTTPStatus.BAD_REQUEST, "body must contain value and optional ttl_seconds")
        else:
            ttl = payload.get("ttl_seconds")
            if ttl is not None and (isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or not math.isfinite(ttl) or ttl <= 0):
                self._error(HTTPStatus.BAD_REQUEST, "ttl_seconds must be a finite number greater than zero")
                return
            replaced = self.store.put(key, payload["value"], ttl)
            self._respond(HTTPStatus.OK if replaced else HTTPStatus.CREATED, {"key": key, "value": payload["value"]})

    def do_DELETE(self) -> None:
        key = self._key()
        if key is None:
            self._error(HTTPStatus.BAD_REQUEST, "invalid key or route")
        elif self.store.delete(key):
            self._respond(HTTPStatus.NO_CONTENT)
        else:
            self._error(HTTPStatus.NOT_FOUND, "key not found")

    def do_POST(self) -> None:
        self._error(HTTPStatus.METHOD_NOT_ALLOWED, "unsupported method")

    def do_PATCH(self) -> None:
        self._error(HTTPStatus.METHOD_NOT_ALLOWED, "unsupported method")


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--host", required=True)
    parser.add_argument("--port", type=int, required=True)
    parser.add_argument("--data", type=Path, required=True)
    args = parser.parse_args()
    Handler.store = Store(args.data)
    server = ThreadingHTTPServer((args.host, args.port), Handler)
    server.daemon_threads = True
    print(f"LISTENING {server.server_port}", flush=True)
    signal.signal(signal.SIGTERM, lambda *_: threading.Thread(target=server.shutdown, daemon=True).start())
    try:
        server.serve_forever()
    finally:
        server.server_close()


if __name__ == "__main__":
    main()

